-- ============================================
-- LUMA — PILOTE x4 : "Un dîner d'affaires à enjeux" (Thème 1, format long)
-- 35 nœuds, 4 fins, branches quasi partout
-- ============================================

update scenarios set content = '{"characters": {"host": "M. Reynolds (client potentiel)"}, "start_node": "n1", "nodes": {"n1": {"speaker": "host", "text": "Thank you for joining me tonight. Shall we start with drinks?", "text_fr": "Merci de m''avoir rejoint ce soir. On commence par les boissons ?", "choices": [{"text": "That sounds great, I''ll have a sparkling water.", "next": "n2a"}, {"text": "I''d love a glass of red wine, thank you.", "next": "n2b"}, {"text": "Actually, could we get straight to business? I have another meeting after.", "next": "n2c"}]}, "n2a": {"speaker": "host", "text": "Sensible choice, keeping a clear head. So, tell me about your company''s plans.", "text_fr": "Choix judicieux, garder les idées claires. Alors, parlez-moi des projets de votre entreprise.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3"}, {"text": "I''d rather hear about your priorities first.", "next": "n3b"}]}, "n2b": {"speaker": "host", "text": "A person who enjoys a good glass, I respect that. So, tell me about your plans.", "text_fr": "Une personne qui apprécie un bon verre, je respecte ça. Alors, parlez-moi de vos projets.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3"}, {"text": "I''d rather hear about your priorities first.", "next": "n3b"}]}, "n2c": {"speaker": "host", "text": "Direct — I like that. Very well, let''s not waste time.", "text_fr": "Direct — j''aime ça. Très bien, ne perdons pas de temps.", "choices": [{"text": "We''re planning to expand into three new markets.", "next": "n3fast"}, {"text": "Let''s start with what matters most to your side.", "next": "n3b"}]}, "n3": {"speaker": "host", "text": "Ambitious! What''s driving that decision?", "text_fr": "Ambitieux ! Qu''est-ce qui motive cette décision ?", "choices": [{"text": "Strong demand and a solid financial position.", "next": "n4"}, {"text": "Honestly, competitive pressure is forcing our hand.", "next": "n4b"}]}, "n3b": {"speaker": "host", "text": "Fair enough. Honestly, we''re looking for a reliable long-term partner.", "text_fr": "Entendu. Honnêtement, on cherche un partenaire fiable sur le long terme.", "choices": [{"text": "That aligns well with what we''re looking for too.", "next": "n4"}, {"text": "Reliability matters, but so does speed of execution.", "next": "n4c"}]}, "n3fast": {"speaker": "host", "text": "Good, straight answers. Let''s talk numbers immediately then.", "text_fr": "Bien, des réponses directes. Parlons chiffres tout de suite alors.", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}, {"text": "Before numbers, I''d like to understand your current suppliers.", "next": "n5c"}]}, "n4": {"speaker": "host", "text": "I like that. Shall we order? I recommend the sea bass.", "text_fr": "J''aime ça. On commande ? Je recommande le bar de mer.", "choices": [{"text": "I''ll trust your recommendation, thank you.", "next": "n5"}, {"text": "I think I''ll go with the steak, if that''s fine.", "next": "n5"}, {"text": "Actually, let''s keep talking business a bit longer first.", "next": "n5b"}]}, "n4b": {"speaker": "host", "text": "Honesty about competitive pressure — that''s rare in these meetings.", "text_fr": "L''honnêteté sur la pression concurrentielle — c''est rare dans ce genre de réunion.", "choices": [{"text": "I believe transparency builds better partnerships.", "next": "n5"}, {"text": "It''s a risk to admit, but I''d rather you hear it from me first.", "next": "n5b"}]}, "n4c": {"speaker": "host", "text": "Speed matters, agreed. Let''s see how fast we can actually move together.", "text_fr": "La rapidité compte, d''accord. Voyons à quelle vitesse on peut vraiment avancer ensemble.", "choices": [{"text": "We could have a pilot running within two weeks.", "next": "n5"}, {"text": "Realistically, a month is safer to do it properly.", "next": "n5b"}]}, "n5c": {"speaker": "host", "text": "We work with two regional suppliers currently, but we''re not fully satisfied.", "text_fr": "On travaille actuellement avec deux fournisseurs régionaux, mais on n''est pas pleinement satisfaits.", "choices": [{"text": "What specifically has been disappointing?", "next": "n5"}, {"text": "We could offer a trial period to prove ourselves.", "next": "n5b"}]}, "n5": {"speaker": "host", "text": "Good choice. Now, about pricing — what flexibility do you have?", "text_fr": "Bon choix. Maintenant, côté tarifs — quelle flexibilité avez-vous ?", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}, {"text": "Let''s finalize the partnership first, then discuss numbers.", "next": "n6b"}, {"text": "I''d need to check with my team before committing to specifics.", "next": "n6c"}]}, "n5b": {"speaker": "host", "text": "I appreciate you being upfront about that. Let''s talk pricing then.", "text_fr": "J''apprécie que vous soyez franc là-dessus. Parlons tarifs alors.", "choices": [{"text": "We can discuss volume discounts for a multi-year deal.", "next": "n6"}, {"text": "I''d rather propose a phased pricing structure.", "next": "n6d"}]}, "n6": {"speaker": "host", "text": "That''s exactly the kind of flexibility we need. But I have a concern — your delivery timelines.", "text_fr": "C''est exactement la flexibilité dont on a besoin. Mais j''ai une préoccupation — vos délais de livraison.", "choices": [{"text": "We can guarantee priority handling for your account.", "next": "n7"}, {"text": "Let me be honest — there could be occasional delays during peak season.", "next": "n7b"}, {"text": "We''re actually investing in a new logistics hub next quarter.", "next": "n7c"}]}, "n6b": {"speaker": "host", "text": "I appreciate that approach. But my board will want numbers eventually.", "text_fr": "J''apprécie cette approche. Mais mon conseil voudra des chiffres à un moment.", "choices": [{"text": "Understood, I''ll have a full proposal ready within the week.", "next": "n7"}]}, "n6c": {"speaker": "host", "text": "Reasonable, though I do value decisiveness in a partner.", "text_fr": "Raisonnable, même si j''apprécie la capacité de décision chez un partenaire.", "choices": [{"text": "I can give you a provisional range tonight, and confirm formally this week.", "next": "n7"}, {"text": "I understand — let me call my team right now to speed things up.", "next": "n7d"}]}, "n6d": {"speaker": "host", "text": "Interesting approach. Walk me through how that would work.", "text_fr": "Approche intéressante. Expliquez-moi comment ça fonctionnerait.", "choices": [{"text": "Lower rates initially, scaling up as volume grows.", "next": "n7"}, {"text": "A fixed rate with a review clause after six months.", "next": "n7c"}]}, "n7": {"speaker": "host", "text": "Good. Last thing — I''ll need this finalized before the end of the month.", "text_fr": "Bien. Dernière chose — j''aurai besoin que ce soit finalisé avant la fin du mois.", "choices": [{"text": "That''s tight, but we can make it work.", "next": "n8"}, {"text": "That''s ambitious — let''s aim for it but stay realistic.", "next": "n8b"}]}, "n7b": {"speaker": "host", "text": "I appreciate the honesty more than empty promises.", "text_fr": "J''apprécie l''honnêteté plus que des promesses vides.", "choices": [{"text": "Trust matters more to me than overselling.", "next": "n8c"}, {"text": "We can offer a service credit for any delay beyond 48 hours.", "next": "n8"}]}, "n7c": {"speaker": "host", "text": "That investment shows real commitment. I''m impressed.", "text_fr": "Cet investissement montre un vrai engagement. Je suis impressionné.", "choices": [{"text": "We''re playing the long game with this partnership.", "next": "n8"}]}, "n7d": {"speaker": "host", "text": "(Your phone buzzes — a rival supplier is calling with a better offer, right now.)", "text_fr": "(Votre téléphone vibre — un fournisseur concurrent appelle avec une meilleure offre, là maintenant.)", "choices": [{"text": "Ignore it completely and stay focused on this dinner.", "next": "n8d"}, {"text": "Glance at it, then set it face-down without answering.", "next": "n8d"}, {"text": "Excuse yourself briefly to check who it is.", "next": "n8e"}]}, "n8": {"speaker": "host", "text": "Good. Let''s put it in writing this week, then.", "text_fr": "Bien. Mettons ça par écrit cette semaine, alors.", "choices": [{"text": "I''ll send the draft contract tomorrow morning.", "next": "n9"}, {"text": "Let''s schedule a call to review every clause together.", "next": "n9b"}]}, "n8b": {"speaker": "host", "text": "I respect that you''re not overpromising. Let''s aim for it together.", "text_fr": "Je respecte que vous ne promettiez pas plus que possible. Visons ça ensemble.", "choices": [{"text": "I''ll send the draft contract tomorrow morning.", "next": "n9"}, {"text": "Let''s schedule a call to review every clause together.", "next": "n9b"}]}, "n8c": {"speaker": "host", "text": "This is exactly the kind of partner I want — honest, even when it''s inconvenient.", "text_fr": "C''est exactement le genre de partenaire que je veux — honnête, même quand c''est inconfortable.", "choices": [{"text": "I''ll send the draft contract tomorrow morning.", "next": "n9c"}]}, "n8d": {"speaker": "host", "text": "(You silence the phone.) Sorry about that. Where were we?", "text_fr": "(Vous coupez le son du téléphone.) Désolé pour ça. Où en étions-nous ?", "choices": [{"text": "You have my full attention — let''s finish this.", "next": "n9"}, {"text": "Just finalizing the delivery timeline commitment.", "next": "n9b"}]}, "n8e": {"speaker": "host", "text": "(He raises an eyebrow slightly as you step away.)", "text_fr": "(Il hausse légèrement un sourcil alors que vous vous éloignez.)", "choices": [{"text": "Sorry, just a work call — nothing more important than this.", "next": "n9d"}, {"text": "(Come back and don''t mention it at all.)", "next": "n9e"}]}, "n9": {"speaker": "host", "text": "Perfect. I''ll have my lawyer review it Friday.", "text_fr": "Parfait. Mon avocat le relira vendredi.", "choices": [{"text": "Sounds great, looking forward to it.", "next": "end_deal"}, {"text": "I''ll make sure it''s airtight on our end too.", "next": "end_deal"}]}, "n9b": {"speaker": "host", "text": "Let''s say Thursday at 2pm — does that work?", "text_fr": "Disons jeudi à 14h — ça vous convient ?", "choices": [{"text": "Perfect, I''ll put it in my calendar right now.", "next": "end_deal"}, {"text": "Actually, could we push it to Friday instead?", "next": "end_realistic"}]}, "n9c": {"speaker": "host", "text": "I trust you on this. No need for extra calls.", "text_fr": "Je vous fais confiance là-dessus. Pas besoin d''appels supplémentaires.", "choices": [{"text": "That trust means a lot — I won''t let you down.", "next": "end_honest"}]}, "n9d": {"speaker": "host", "text": "Good to know where your priorities lie. Let''s continue.", "text_fr": "Bon de savoir où sont vos priorités. Continuons.", "choices": [{"text": "This partnership is what matters most to me right now.", "next": "end_deal"}]}, "n9e": {"speaker": "host", "text": "(He seems a bit less warm for the rest of dinner, but continues professionally.)", "text_fr": "(Il semble un peu moins chaleureux pour le reste du dîner, mais continue professionnellement.)", "choices": [{"text": "I sense some hesitation — is everything alright?", "next": "end_realistic"}, {"text": "(Push forward with the deal terms anyway.)", "next": "end_cautious"}]}, "end_deal": {"speaker": "host", "text": "Looking forward to it. This could be the start of something great.", "text_fr": "J''ai hâte. Ça pourrait être le début de quelque chose de formidable.", "end": true, "ending_label": "Partenariat scellé avec enthousiasme 🤝"}, "end_realistic": {"speaker": "host", "text": "I respect that you''re not overpromising. Let''s aim for it together.", "text_fr": "Je respecte que vous ne promettiez pas plus que possible. Visons ça ensemble.", "end": true, "ending_label": "Partenariat réaliste et solide 🤝"}, "end_honest": {"speaker": "host", "text": "This is exactly the kind of partner I want — honest, even when it''s inconvenient.", "text_fr": "C''est exactement le genre de partenaire que je veux — honnête, même quand c''est inconfortable.", "end": true, "ending_label": "Confiance gagnée par l''honnêteté 💎"}, "end_cautious": {"speaker": "host", "text": "We''ll move forward, but I''ll admit I''m keeping a closer eye on this one.", "text_fr": "On avance, mais j''avoue que je vais surveiller celui-là de plus près.", "end": true, "ending_label": "Accord signé, mais confiance fragile ⚠️"}}}'::jsonb, is_playable = true
where title = 'Un dîner d''affaires à enjeux'
  and theme_id = (select id from scenario_themes where position = 1 and language_id = (select id from languages where code = 'en'));
